from html import escape as E
import json
from pathlib import Path
W=json.loads((Path(__file__).parent/'wissen.json').read_text(encoding='utf-8'))
TYPES={
 'de':[
 ['anna','Kleinprojekt und Einzeledition','Anna erarbeitet eine kommentierte Edition','Eine Editorin, ein begrenztes Budget und wenig technische Unterstützung. Wie viel Git braucht ein überschaubares Editionsvorhaben?','anna.png'],
 ['albrecht','Großprojekt und Langzeitedition','Historisch-kritische Albrecht-Edition','Große, verteilte Teams arbeiten über Jahrzehnte an einer gemeinsamen Edition. Wie bleiben Regeln, Qualität und Arbeitswissen über Personalwechsel hinweg erhalten?','albrecht.png'],
 ['korpus','Korpus und Publikationsrepositorium','Rätselhaft! – ein Korpus für neue Forschung','Git als öffentlicher Datenspeicher: Ein Korpus soll als wissenschaftliche Publikation verständlich, verlässlich und für andere Forschende direkt nutzbar sein.','korpus.png'],
 ['drittmittel','Drittmittelprojekt mit kleinem Team','Die andere Stadt – eine genetische Edition','Ein kleines Team, Qualifikationsstellen und eine wissenschaftliche Edition nach modernen Maßstäben. Wie passen Buch, Editionsfrontend, Dissertationen und befristete Förderung zusammen?','drittmittel.png']],
 'en':[
 ['anna','Small project and individual edition','Anna prepares an annotated edition','One editor, a limited budget and little technical support. How much Git does a manageable editorial undertaking need?','anna.png'],
 ['albrecht','Large project and long-term edition','The Albrecht historical-critical edition','Large, distributed teams work on a shared edition over decades. How can rules, quality and working knowledge survive changes in personnel?','albrecht.png'],
 ['korpus','Corpus and publication repository','Rätselhaft! – a corpus for new research','Git as a public data repository: a corpus needs to be an understandable, reliable scholarly publication that other researchers can use directly.','korpus.png'],
 ['drittmittel','Grant-funded project with a small team','Die andere Stadt – a genetic edition','A small team, doctoral research posts and a scholarly edition meeting modern standards. How can a book, editorial frontend, dissertations and fixed-term funding work together?','drittmittel.png']]
}
def project_cards(lang,url):
 de=lang=='de';out='<div class="project-grid">'
 for key,title,subtitle,text,img in TYPES[lang]:
  target=url('full_'+('stadt' if key=='drittmittel' else key),lang)
  label='Vollständiges Projekt erkunden →' if de else 'Explore the full project →'
  out+='<article class="project-card"><figure><img src="/assets/'+img+'" alt="" width="1536" height="1024" loading="lazy"><figcaption>'+('KI-generierte Illustration' if de else 'AI-generated illustration')+'</figcaption></figure><h2>'+title+'</h2><p class="project-subtitle">'+subtitle+'</p><p>'+text+'</p><a href="'+target+'"'+(' hreflang="'+lang+'"')+'>'+label+'</a></article>'
 return out+'</div>'

def perspectives(lang):
 return ('<h2>Unsere Repositorien werden gelesen.</h2><p>Nicht nur die veröffentlichten Editionsdaten sind eine interessante Lektüre. Gerade Arbeitsrepositorien können faszinierende Quellen sein: Sie bewahren Spuren von Entscheidungen, Zusammenarbeit, Umwegen und Veränderungen.</p><p>Es gibt berechtigte Interessen, diese Quellen mit editorischer Gründlichkeit zu lesen – etwa beim Einstieg in ein Team, bei einer Begutachtung oder bei der Erforschung editorischer Praxis. Dabei werden Zusammenhänge sichtbar, die wir beim eigenen Arbeiten vielleicht gar nicht im Blick hatten. Auch eine KI-gestützte Auswertung kann unerwartete Zugänge eröffnen.</p><p>Wir stellen vier ausgewählte Perspektiven vor. Wer den Einsatz von Git plant, ist eingeladen, diese Blickwinkel mitzudenken: Was sollen andere verstehen können? Was dürfen sie lesen und auswerten? Und welche Schlüsse tragen die gespeicherten Spuren tatsächlich?</p>' if lang=='de' else '<h2>Others will read our repositories.</h2><p>Published edition data are not the only interesting reading. Working repositories can be fascinating sources, preserving traces of decisions, collaboration, detours and changes.</p><p>There are legitimate reasons to read these sources with editorial care: joining a team, reviewing a project or researching editorial practice. Such readings may reveal connections we did not notice while working. AI-assisted analysis can also open up unexpected perspectives.</p><p>We present four selected perspectives. If you are planning to use Git, consider these viewpoints: what should others be able to understand? What may they read and analyse? And which conclusions do the recorded traces actually support?</p>')

def short_perspectives(lang,url):
 return '<section class="section sage"><div class="prose">'+('<h2>Wer liest unser Git – und mit welchem Blick?</h2><p>Auch unsere Arbeitsrepositorien können mit editorischer Gründlichkeit gelesen werden: von neuen Mitarbeitenden, Gutachtenden, Forschenden oder mit KI-Unterstützung. Vier ausgewählte Perspektiven zeigen berechtigte Interessen und unerwartete Blickwinkel. Sie helfen uns, vorab über Verständlichkeit, Zugänge und Verantwortung nachzudenken.</p>' if lang=='de' else '<h2>Who reads our Git, and from which perspective?</h2><p>Our working repositories, too, may be read with editorial care: by newcomers, reviewers, researchers or with AI assistance. Four selected perspectives reveal legitimate interests and unexpected viewpoints. They help us consider clarity, access and responsibility in advance.</p>')+'<a href="'+url('perspectives',lang)+'">'+('Perspektiven wechseln →' if lang=='de' else 'Change perspective →')+'</a></div></section>'

def about(lang,url):
 de=lang=='de'
 return '<section class="page-head"><p class="eyebrow">Editionskompass</p><h1>'+('Eine Einladung an die Editionswissenschaft.' if de else 'An invitation to scholarly editors.')+'</h1><p class="lead">'+('Sie interessieren sich für Git und möchten herausfinden, was es für Ihre editorische Arbeit leisten kann? Hier beginnen wir bei Ihren Fragen.' if de else 'Interested in Git and what it could offer your editorial work? We start with your questions.')+'</p></section><section class="section narrow"><h2>'+('Technik und editorische Verantwortung zusammendenken' if de else 'Bring technology and editorial responsibility together')+'</h2><p>'+('Git wird oft den technischen Partnern eines Projekts überlassen. Doch es kann nicht nur Entscheidungen bewahren, sondern auch ihre Entstehung dokumentieren und Zusammenarbeit gestalten. Welche Arbeitsweise fachlich sinnvoll ist und welche Spuren bewahrt, geteilt oder ausgewertet werden sollen, braucht editionswissenschaftliche Entscheidungen. Technische Beratung und editorische Verantwortung gehören zusammen.' if de else 'Git is often left to a project’s technical partners. Yet it can preserve decisions, document their development and shape collaboration. Choosing suitable working practices and deciding which traces to preserve, share or analyse requires editorial judgement. Technical advice and editorial responsibility belong together.')+'</p><h2>'+('Vier Projekttypen als Orientierung' if de else 'Four project types for orientation')+'</h2><p>'+('Vom Einzelprojekt über die Langzeitedition bis zum öffentlichen Korpus und zum typischen Drittmittelprojekt: Kein Vorhaben gleicht dem anderen. Die fiktiven Beispiele machen typische Entscheidungen greifbar. Sie laden dazu ein, das eigene Projekt wiederzuerkennen und eine passende Git-Strategie vorzubereiten – auch beim Schreiben eines Antrags oder im Workshop.' if de else 'From an individual project and a long-term edition to a public corpus and a typical grant-funded project: no two undertakings are alike. Fictional examples make common decisions tangible, helping you recognise your situation and prepare an appropriate Git strategy, including for a proposal or workshop.')+'</p>'+perspectives(lang)+'<h2>'+('Erkunden, ausprobieren, mitnehmen' if de else 'Explore, try, take away')+'</h2><p>'+('Geschichten führen in ein Thema ein. Merksätze, praktische Empfehlungen und Vorlagen führen zum eigenen Handeln. Mythos/Fakt und Antipatterns laden als freiwillige kleine Herausforderungen zum Ausprobieren ein. Niemand muss alle Fragen beantworten. Alle 108 Themen stehen zusätzlich gesammelt zum Lesen und Herunterladen bereit.' if de else 'Stories introduce a topic; takeaways, practical recommendations and templates help you act. Myth/fact and antipattern questions offer optional short challenges. Nobody needs to answer every question. All 108 topics are also collected for reading and download.')+'</p><div class="actions"><a href="'+url('projects',lang)+'">'+('Projekttyp wählen' if de else 'Choose a project type')+'</a><a href="'+url('knowledge',lang)+'">'+('Wissen kompakt' if de else 'Compact knowledge')+'</a><a href="'+url('sources',lang)+'">'+('Quellen und KI-Einsatz' if de else 'Sources and AI use')+'</a></div></section>'

def knowledge(lang):
 de=lang=='de';out='<article class="knowledge-document"><section class="page-head"><p class="eyebrow">'+('Lesefassung · Alle Themen' if de else 'Reading edition · All topics')+'</p><h1>'+('Git-Wissen kompakt' if de else 'Compact Git knowledge')+'</h1><p class="lead">'+('83 Aussagen mit Einordnung, 25 Antipatterns mit Handlungsempfehlungen und 24 Begriffe. Ohne Spiel und ohne Freischaltung vollständig nutzbar.' if de else '83 statements with explanations, 25 antipatterns with recommended practices and 24 terms. Fully available without playing or unlocking anything.')+'</p><div class="resource-actions no-print"><a download href="/assets/wissen-'+lang+'.pdf">PDF</a><a download href="/assets/wissen-'+lang+'.md">Markdown</a><button data-print-page>'+('Drucken' if de else 'Print')+'</button></div></section><section class="section"><h2>'+('Mythos oder Fakt? Die Einordnung.' if de else 'Myth or fact? The explanation.')+'</h2><div class="knowledge-grid">'
 for n in W['nodes']:
  x=n if de else n['en'];title=x.get('claim',x['title']);detail=x.get('detail') or ' '.join(x.get(k,'') for k in ['surprise','utility','limits'])
  out+='<section class="knowledge-item" id="wissen-'+n['id']+'"><p class="eyebrow">'+n['id']+' · '+(('Irrtum' if de else 'Myth') if n['kind']=='M' else ('Fakt' if de else 'Fact'))+'</p><h3>'+E(title)+'</h3><p>'+E(detail)+'</p></section>'
 out+='</div></section><section class="section"><h2>'+('Antipatterns erkennen und besser handeln' if de else 'Recognise antipatterns and improve practice')+'</h2><p>'+('Eine zunächst plausible Lösung kann unter bestimmten Bedingungen Nachteile erzeugen. Die Geltungsgrenze nennt Fälle, in denen die Praxis dennoch sinnvoll ist.' if de else 'A seemingly plausible solution can create disadvantages in particular conditions. The boundary explains when the practice may still be appropriate.')+'</p><div class="knowledge-grid">'
 for c in W['academy'][lang]['cards']:
  out+='<section class="knowledge-item" id="antipattern-'+c['code']+'"><p class="eyebrow">'+c['code']+'</p><h3>'+E(c['title'])+'</h3><p><strong>'+('Muster: ' if de else 'Pattern: ')+'</strong>'+E(c['bad'])+'</p><p><strong>'+('Besser: ' if de else 'Better: ')+'</strong>'+E(c['good'])+'</p><p><strong>'+('Geltungsgrenze: ' if de else 'Boundary: ')+'</strong>'+E(c['boundary'])+'</p></section>'
 out+='</div></section><section class="section"><h2>'+('Begriffe' if de else 'Terms')+'</h2><div class="knowledge-grid">'
 for g in W['glossary']:
  x=g if de else g['en'];out+='<section class="knowledge-item"><h3>'+E(x['term'])+'</h3><p>'+E(x['description'])+'</p></section>'
 return out+'</div><p class="small">'+('Grundlagen: Git-Entdeckungsreise (83 Aussagen, 24 Begriffe) und Git Antipattern Academy (25 Karten). Alle Themen der beiden Sammlungen sind enthalten; Beziehungsgraphen und ausführliche Spielszenarien gehören nicht zu dieser kompakten Lesefassung.' if de else 'Sources: Git Discovery (83 statements, 24 terms) and Git Antipattern Academy (25 cards). All topics from both collections are included; relationship graphs and extended game scenarios are outside this compact reading edition.')+'</p></section></article>'

def game(lang,url):
 de=lang=='de'
 return '<section class="page-head"><p class="eyebrow">'+('Freiwillige Herausforderung' if de else 'Optional challenge')+'</p><h1>'+('Lust auf ein kleines Quiz?' if de else 'Fancy a quick quiz?')+'</h1><p class="lead">'+('Mythos oder Fakt? Gute Idee oder Antipattern? Testen Sie Ihr Gespür in fünf zufälligen Fragen. Für jeden Treffer gibt es einen Punkt und zu jeder Antwort die Erklärung. Mal sehen, wie viele Sie knacken! Sie können jederzeit aufhören oder direkt alles nachlesen.' if de else 'Myth or fact? Good idea or antipattern? Test your instincts with five random questions. Each correct answer earns a point, and every answer comes with an explanation. How many can you crack? Stop whenever you like or read everything directly.')+'</p><div class="actions"><button class="button" id="game-start">'+('Mythos/Fakt spielen' if de else 'Play myth/fact')+'</button><button class="button secondary" id="game-antipattern">'+('Antipatterns spielen' if de else 'Play antipatterns')+'</button><a href="'+url('knowledge',lang)+'">'+('Lieber alle Themen lesen →' if de else 'Read all topics instead →')+'</a></div></section><section class="section narrow" id="game-stage" aria-live="polite"><p>'+('Wählen Sie Ihre Disziplin – und los geht’s! Ihr Punktestand bleibt nur auf dieser Seite.' if de else 'Pick your challenge and off you go! Your score stays on this page only.')+'</p></section>'
